   function lookup_sc_field_3(&$conteudo, $validate=false)
   {
      global  $sc_field_3;
      $guarda_formatado = $this->formatado;
      if (!$validate)
      {
          $this->nm_tira_formatacao();
      }
      if (!$validate)
      {
          $Salva_opc = $this->nmgp_opcao;
          $this->nmgp_opcao = "lookup_rpc";
          $this->nm_converte_datas();
          $this->nmgp_opcao = $Salva_opc;
      }
      if (in_array(strtolower($this->Ini->nm_con_comum['tpbanco']), $this->Ini->nm_bases_ibase))
      { 
          $GLOBALS["NM_ERRO_IBASE"] = 1;  
      } 
      $nm_comando = "SELECT \"nome-abrev\" 
FROM PUB.emitente 
WHERE \"cod-emitente\" = $this->sc_field_3 
ORDER BY \"nome-abrev\""; 
      if ($this->sc_field_3 == "")
      { 
          $conteudo = ""; 
          if (!$validate)
          {
              $this->nm_formatar_campos();
          }
          return; 
      } 
      $_SESSION['scriptcase']['sc_sql_ult_comando'] = $nm_comando; 
      $_SESSION['scriptcase']['sc_sql_ult_conexao'] = ''; 
      if ($rs = $this->Ini->nm_db_comum->Execute($nm_comando)) 
      {
          $conteudo = (isset($rs->fields[0])) ? $rs->fields[0] : "Fornecedor Não Encontrado"; 
          $this->Erro_look_sc_field_3 = (isset($rs->fields[0])) ? "" : "Fornecedor Não Encontrado"; 
          $rs->Close() ; 
      } 
      elseif ($GLOBALS["NM_ERRO_IBASE"] != 1)  
      {  
          $this->Erro->mensagem(__FILE__, __LINE__, "banco", $this->Ini->Nm_lang['lang_errm_dber'], $this->Ini->nm_db_comum->ErrorMsg()); 
          exit; 
      } 
      $GLOBALS["NM_ERRO_IBASE"] = 0; 
      if (!$validate)
      {
          foreach ($this->Before_unformat as $Cmp => $Val)
          {
              $this->$Cmp = $Val;
              $this->formatado = $guarda_formatado;
          }
      }
   }
