      }
      if ('' !== $this->cod_armador || (!empty($format_fields) && isset($format_fields['cod_armador'])))
      {
          nmgp_Form_Num_Val($this->cod_armador, $this->field_config['cod_armador']['symbol_grp'], $this->field_config['cod_armador']['symbol_dec'], "0", "S", $this->field_config['cod_armador']['format_neg'], "", "", "-", $this->field_config['cod_armador']['symbol_fmt']) ; 
      }
      if ('' !== $this->situacao || (!empty($format_fields) && isset($format_fields['situacao'])))
      {
          nmgp_Form_Num_Val($this->situacao, $this->field_config['situacao']['symbol_grp'], $this->field_config['situacao']['symbol_dec'], "0", "S", $this->field_config['situacao']['format_neg'], "", "", "-", $this->field_config['situacao']['symbol_fmt']) ; 
