      {
          nmgp_Form_Num_Val($this->perc_custo, $this->field_config['perc_custo']['symbol_grp'], $this->field_config['perc_custo']['symbol_dec'], "2", "S", $this->field_config['perc_custo']['format_neg'], "", "", "-", $this->field_config['perc_custo']['symbol_fmt']) ; 
