   function NM_gera_log_output() 
   {
       $Log_output = "";
       $prim_delim = "";
       $Log_labels = array();
       $Log_labels['num-pedido'] =  "Num Pedido";
       $Log_labels['cod-estabel'] =  "Estab.";
       $Log_labels['nome-ab-forn'] =  "Nome Ab Forn";
       $Log_labels['cod-emit-forn'] =  "Fornecedor";
       $Log_labels['narrativa'] =  "Narrativa";
       $Log_labels['usuario'] =  "Usuario";
       $Log_labels['dt-compra'] =  "Dt Compra";
       $Log_labels['char-1'] =  "Char 1";
       $Log_labels['dec-1'] =  "Vl.Dolar Venda";
       $Log_labels['int-1'] =  "Int 1";
       $Log_labels['log-1'] =  "Log 1";
       $Log_labels['data-1'] =  "Data 1";
       $Log_labels['comprador'] =  "Comprador";
       $Log_labels['dt-recebimento'] =  "Dt Recebimento";
       $Log_labels['dt-prev-chegada'] =  "Dt Prev Chegada";
       $Log_labels['situacao'] =  "Situação ERP";
       $Log_labels['vlr-frete'] =  "Vlr Frete";
       $Log_labels['vlr-seguro'] =  "Vlr Seguro";
       $Log_labels['vlr-despesas'] =  "Vlr Despesas";
       $Log_labels['exclusivo'] =  "Exclusivo";
       $Log_labels['vl-dolar-venda'] =  "Vl Dolar Venda";
       $Log_labels['vl-dolar-compra'] =  "Vl Dolar Compra";
       $Log_labels['log_liberar_custo_realizado'] =  "Liberar Custo Realizado?";
       $Log_labels['medidas_container'] =  "Medidas Container";
       $Log_labels['dt_prev_embarque'] =  "Dt. Prev. Embarque";
       $Log_labels['dt_real_embarque'] =  "Dt Real Embarque";
       $Log_labels['situacao_container_id'] =  "Situação Acompanhamento";
       $Log_labels['ind_dt_embarque'] =  "Sit.Dt.Embarque";
       $Log_labels['ind_dt_prev_chegada'] =  "Sit.Dt.Prev.Chegada";
       $Log_labels['ordem_busca_dolar_di'] =  "Ordem Busca Dolar Di";
       $Log_labels['log_pagto_final'] =  "Pagto Final Realizado?";
       $Log_labels['cod_agente_cargas'] =  "Agente Cargas";
       $Log_labels['cod_armador'] =  "Armador";
       $Log_labels['cod_tipo_calculo'] =  "Tipo Cálculo";
       $Log_labels['perc_custo'] =  "% Custo";
       $Log_labels['vl_dolar_di'] =  "Vl.Dolar DI";
       $Log_labels['log_gerar_saldo_a_pagar'] =  "Considera Cta. Corrente Fornecedor?";
       $Log_labels['log_gerar_distr_custo'] =  "Gerar Distr. Custo?";
       $Log_labels['ordem_busca_dolar_compra'] =  "Ordem Busca Dólar Compra";
       $Log_labels['cod_tipo_proj_dolar'] =  "Tipo Projeção";
       $Log_labels['vl_proj_dolar'] =  "Vl. Acresc. Proj. Dolar";
       $Log_labels['log_versao_custo_desatualizada'] =  "Versão de Custo Desatualizada?";
       $Log_labels['dt_hr_ult_alt_versao_custo'] =  "Dt.Hr.Ult.Alt.Versão Custo";
       $Log_labels['ptax'] =  "Ptax";
       $Log_labels['cod-depos'] =  "Cod Depos";
       $Log_labels['dt_prev_chegada_loja'] =  "Dt Prev Chegada Loja";
       $Log_labels['estacao'] =  "Estação";
       foreach ($this->SC_log_arr as $type => $dats)
       {
           if ($type == "keys")
           {
               $Log_output .= "--> keys <-- ";
               foreach ($dats as $key => $data)
               {
                   $Log_output .=  $prim_delim . $key . " : " . $data;
                   $prim_delim  = "||";
               }
           }
           if ($type == "fields")
           {
               $Log_output .= $prim_delim . "--> fields <-- ";
               $prim_delim = "";
               if (empty($dats) && $this->SC_log_evt == "update")
               {
                   return;
               }
               foreach ($dats as $key => $data)
               {
                   foreach ($data as $tp => $val)
                   {
                      $tpok = ($tp == 0) ? " (old) " : " (new) ";
                      $Log_output .= $prim_delim . $key . $tpok . " : " . $val;
                      $prim_delim  = "||";
                   }
                   $Log_output .= $prim_delim . $key . " (label) " . " : " . $Log_labels[$key];
               }
           }
       }
       $this->NM_gera_log_insert("Scriptcase", $this->SC_log_evt, $Log_output);
   }
        function initializeRecordState() {
                $_SESSION['sc_session'][$this->Ini->sc_page]['form_pp_container']['record_state'] = array();
        }

        function storeRecordState($sc_seq_vert = 0) {
                if (!isset($_SESSION['sc_session'][$this->Ini->sc_page]['form_pp_container']['record_state'])) {
                        $this->initializeRecordState();
                }
                if (!isset($_SESSION['sc_session'][$this->Ini->sc_page]['form_pp_container']['record_state'][$sc_seq_vert])) {
                        $_SESSION['sc_session'][$this->Ini->sc_page]['form_pp_container']['record_state'][$sc_seq_vert] = array();
                }

                $_SESSION['sc_session'][$this->Ini->sc_page]['form_pp_container']['record_state'][$sc_seq_vert]['buttons'] = array(
                        'delete' => $this->nmgp_botoes['delete'],
                        'update' => $this->nmgp_botoes['update']
                );
        }

        function loadRecordState($sc_seq_vert = 0) {
                if (!isset($_SESSION['sc_session'][$this->Ini->sc_page]['form_pp_container']['record_state']) || !isset($_SESSION['sc_session'][$this->Ini->sc_page]['form_pp_container']['record_state'][$sc_seq_vert])) {
                        return;
                }

                if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['form_pp_container']['record_state'][$sc_seq_vert]['buttons']['delete'])) {
                        $this->nmgp_botoes['delete'] = $_SESSION['sc_session'][$this->Ini->sc_page]['form_pp_container']['record_state'][$sc_seq_vert]['buttons']['delete'];
                }
                if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['form_pp_container']['record_state'][$sc_seq_vert]['buttons']['update'])) {
                        $this->nmgp_botoes['update'] = $_SESSION['sc_session'][$this->Ini->sc_page]['form_pp_container']['record_state'][$sc_seq_vert]['buttons']['update'];
                }
        }

