function local_atribuir_nome_abrev()
{
$_SESSION['scriptcase']['form_pp_container']['contr_erro'] = 'on';
  
$this->sc_field_2  = $this->buscarNomeAbrevFornecedor($this->sc_field_3 );


$_SESSION['scriptcase']['form_pp_container']['contr_erro'] = 'off';
}
function local_exibir_cps_dolar()
{
$_SESSION['scriptcase']['form_pp_container']['contr_erro'] = 'on';
  
switch($this->ordem_busca_dolar_compra ){
	
	case 2:		
		$this->sc_field_readonly("sc_field_17", 'off');
		$this->nmgp_cmp_hidden["cod_tipo_proj_dolar"] = 'on'; $this->NM_ajax_info['fieldDisplay']['cod_tipo_proj_dolar'] = 'on'; 
		$this->nmgp_cmp_hidden["vl_proj_dolar"] = 'on'; $this->NM_ajax_info['fieldDisplay']['vl_proj_dolar'] = 'on'; 
		
	break;
	default:
		$vl_dolar_compra  = 0;
		$this->sc_field_readonly("sc_field_17", 'on');
	    $this->nmgp_cmp_hidden["cod_tipo_proj_dolar"] = 'off'; $this->NM_ajax_info['fieldDisplay']['cod_tipo_proj_dolar'] = 'off'; 
		$this->nmgp_cmp_hidden["vl_proj_dolar"] = 'off'; $this->NM_ajax_info['fieldDisplay']['vl_proj_dolar'] = 'off'; 
	    $this->cod_tipo_proj_dolar  = 1; 
	     
	
}
$_SESSION['scriptcase']['form_pp_container']['contr_erro'] = 'off';
}
function log_pagto_final_onChange()
{
$_SESSION['scriptcase']['form_pp_container']['contr_erro'] = 'on';
  
$original_sc_field_10 = $this->sc_field_10;
$original_log_pagto_final = $this->log_pagto_final;
$original_sc_field_17 = $this->sc_field_17;
$original_ordem_busca_dolar_compra = $this->ordem_busca_dolar_compra;

$vlCotacao = $this->getCotacaoUltPagto($this->sc_field_10 );
if($vlCotacao <> 0 and $this->log_pagto_final  == 1) {
	$this->sc_field_17  = $vlCotacao;
	$this->ordem_busca_dolar_compra  = 2;	
}


$modificado_sc_field_10 = $this->sc_field_10;
$modificado_log_pagto_final = $this->log_pagto_final;
$modificado_sc_field_17 = $this->sc_field_17;
$modificado_ordem_busca_dolar_compra = $this->ordem_busca_dolar_compra;
$this->nm_formatar_campos('sc_field_10', 'log_pagto_final', 'sc_field_17', 'ordem_busca_dolar_compra');
if ($original_sc_field_10 !== $modificado_sc_field_10 || isset($this->nmgp_cmp_readonly['sc_field_10']) || (isset($bFlagRead_sc_field_10) && $bFlagRead_sc_field_10))
{
    $this->ajax_return_values_sc_field_10(true);
}
if ($original_log_pagto_final !== $modificado_log_pagto_final || isset($this->nmgp_cmp_readonly['log_pagto_final']) || (isset($bFlagRead_log_pagto_final) && $bFlagRead_log_pagto_final))
{
    $_SESSION['sc_session'][$this->Ini->sc_page]['form_pp_container']['dados_form']['log_pagto_final'] = $this->log_pagto_final;
    $this->ajax_return_values_log_pagto_final(true);
}
if ($original_sc_field_17 !== $modificado_sc_field_17 || isset($this->nmgp_cmp_readonly['sc_field_17']) || (isset($bFlagRead_sc_field_17) && $bFlagRead_sc_field_17))
{
    $this->ajax_return_values_sc_field_17(true);
}
if ($original_ordem_busca_dolar_compra !== $modificado_ordem_busca_dolar_compra || isset($this->nmgp_cmp_readonly['ordem_busca_dolar_compra']) || (isset($bFlagRead_ordem_busca_dolar_compra) && $bFlagRead_ordem_busca_dolar_compra))
{
    $this->ajax_return_values_ordem_busca_dolar_compra(true);
}
$this->NM_ajax_info['event_field'] = 'log';
form_pp_container_pack_ajax_response();
exit;


$_SESSION['scriptcase']['form_pp_container']['contr_erro'] = 'off';
}
function ordem_busca_dolar_compra_onChange()
{
$_SESSION['scriptcase']['form_pp_container']['contr_erro'] = 'on';
  
$original_ordem_busca_dolar_compra = $this->ordem_busca_dolar_compra;
$original_sc_field_17 = $this->sc_field_17;
$original_cod_tipo_proj_dolar = $this->cod_tipo_proj_dolar;
$original_vl_proj_dolar = $this->vl_proj_dolar;

$this->local_exibir_cps_dolar();

$modificado_ordem_busca_dolar_compra = $this->ordem_busca_dolar_compra;
$modificado_sc_field_17 = $this->sc_field_17;
$modificado_cod_tipo_proj_dolar = $this->cod_tipo_proj_dolar;
$modificado_vl_proj_dolar = $this->vl_proj_dolar;
$this->nm_formatar_campos('ordem_busca_dolar_compra', 'sc_field_17', 'cod_tipo_proj_dolar', 'vl_proj_dolar');
if ($original_ordem_busca_dolar_compra !== $modificado_ordem_busca_dolar_compra || isset($this->nmgp_cmp_readonly['ordem_busca_dolar_compra']) || (isset($bFlagRead_ordem_busca_dolar_compra) && $bFlagRead_ordem_busca_dolar_compra))
{
    $this->ajax_return_values_ordem_busca_dolar_compra(true);
}
if ($original_sc_field_17 !== $modificado_sc_field_17 || isset($this->nmgp_cmp_readonly['sc_field_17']) || (isset($bFlagRead_sc_field_17) && $bFlagRead_sc_field_17))
{
