function decrNivelCorrenteLogDb()
{
$_SESSION['scriptcase']['form_pp_container']['contr_erro'] = 'on';
  
    if(isset($_SESSION['log_db']['nivel_corrente'])){
        $_SESSION['log_db']['nivel_corrente'] -= 1 ;
