function verificarDespesaContainerManual($container,$despesa)
{
$_SESSION['scriptcase']['form_pp_container']['contr_erro'] = 'on';
  
    $log = 0;
    $aRet = $this->getDadosDespesaContainer($container,$despesa,'log_manual');
