    function getSummaryLine()
    {
        $summaryLine = "[" . $this->Ini->Nm_lang['lang_othr_smry_info_simp'] . "]";
        $summaryLine = str_replace(
            [
                '?final?',
                '?total?',
            ],
            [
                $_SESSION['sc_session'][$this->Ini->sc_page]['form_pp_container']['reg_start'] + 1,
                $_SESSION['sc_session'][$this->Ini->sc_page]['form_pp_container']['total'] + 1,
            ],
            $summaryLine
        );

        return $summaryLine;
    } // getSummaryLine

    function scGetColumnOrderRule($fieldName, &$orderColName, &$orderColOrient, &$orderColRule)
    {
        $sortRule = 'nosort';
        if ($_SESSION['sc_session'][$this->Ini->sc_page]['form_pp_container']['ordem_cmp'] == $fieldName) {
            $orderColName = $fieldName;
            if ($_SESSION['sc_session'][$this->Ini->sc_page]['form_pp_container']['ordem_ord'] == " desc") {
                $orderColOrient = $nome_img = $this->Ini->Label_sort_desc;
                $orderColRule = $sortRule = 'desc';
            } else {
                $orderColOrient = $nome_img = $this->Ini->Label_sort_asc;
                $orderColRule = $sortRule = 'asc';
            }
        }
        return $sortRule;
    }

    function scGetColumnOrderIcon($fieldName, $sortRule)
    {        if ('desc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_desc . "\" class=\"sc-ui-img-order-column\" id=\"sc-id-img-order-" . $fieldName . "\" />";
        } elseif ('asc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_asc . "\" class=\"sc-ui-img-order-column\" id=\"sc-id-img-order-" . $fieldName . "\" />";
        } elseif ('' != $this->Ini->Label_sort) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort . "\" class=\"sc-ui-img-order-column\" id=\"sc-id-img-order-" . $fieldName . "\" />";
        } else {
            return '';
        }
    }

    function scIsFieldNumeric($fieldName)
    {
        switch ($fieldName) {
            case "\"nr-container\"":
                return true;
            case "\"cod-emit-forn\"":
                return true;
            case "cod_agente_cargas":
                return true;
            case "cod_armador":
                return true;
            case "situacao":
                return true;
            case "perc_custo":
                return true;
            case "\"vl-dolar-compra\"":
                return true;
            case "vl_proj_dolar":
                return true;
            case "vl_dolar_di":
                return true;
            case "\"vl-dolar-venda\"":
                return true;
            case "ptax":
                return true;
            case "\"num-pedido\"":
                return true;
            case "\"dec-1\"":
                return true;
            case "\"int-1\"":
                return true;
            case "\"vlr-frete\"":
                return true;
            case "\"vlr-seguro\"":
                return true;
            case "\"vlr-despesas\"":
                return true;
            default:
                return false;
        }
        return false;
    }

